def low_stock(request):
    alerts = []
    for product in Product.objects.filter(active=True):
        stock = StockLevel.objects.filter(product=product).aggregate(total=Sum("quantity"))["total"] or 0
        if stock < product.reorder_point:
            alerts.append({"sku": product.sku, "stock": stock})
    return JsonResponse({"alerts": alerts})

